-- Staging restore of what the pre-load saved (Supabase -> Aurora migration, vitana-aurora-staging only). Run AFTER the
-- DMS full load and AFTER staging-db-vector-postload.sql, through
--   bash scripts/aws/staging-db-migration.sh post-load --cluster vitana-aurora-staging
-- One Data API transaction: all or nothing. Re-runnable: each object is only created while it is missing.
--   1. Refuses unless the 13 vector columns are vector again (the vector post-load ran).
--   2. Owner decision R2 (VTID-05023): no foreign key from public into auth on Aurora. Any that exists (for example
--      from a migration replay that the pre-load did not see) is saved with references_auth = true, then dropped.
--   3. Recreates the saved indexes (IF NOT EXISTS).
--   4. Recreates every saved foreign key except the public -> auth ones, as NOT VALID. That is the same choice as the
--      production aurora-cutover-recreate-foreign-keys.sql: enforced for new writes, visible to PostgREST, no scan of
--      the loaded rows.
--   5. Recreates the saved views, shallowest first (a view before the views on it), with their options, grants and
--      comment.
--   6. Asserts the end state: every restorable object is back, and there are 0 foreign keys from public into auth.
--      Otherwise it raises and rolls everything back.
-- No row is changed or deleted.

-- 1. Guards.
DO $guard$ DECLARE s text; bad text; BEGIN SELECT n.nspname INTO s FROM pg_extension e JOIN pg_namespace n ON n.oid = e.extnamespace WHERE e.extname = 'vector'; IF s IS NULL THEN RAISE EXCEPTION 'staging restore: the vector extension is not installed; nothing changed'; END IF; PERFORM set_config('search_path', 'public, ' || quote_ident(s), true); IF to_regclass('migration_audit.saved_foreign_keys') IS NULL THEN RAISE EXCEPTION 'staging restore: migration_audit is missing (the pre-load did not run); nothing changed'; END IF; SELECT string_agg(x.tbl || '.' || x.col, ', ') INTO bad FROM (VALUES ('ai_memory','embedding'),('calendar_events','embedding'),('dev_agent_memory','embedding'),('feedback_tickets','embedding'),('mem_episodes','embedding'),('mem_facts','embedding'),('memory_embeddings','embedding'),('memory_facts','embedding'),('memory_items','embedding'),('user_intents','embedding'),('user_intents','embedding_v2'),('vtid_ledger','embedding'),('vtid_ledger','embedding_v2')) AS x(tbl, col) LEFT JOIN pg_attribute a ON a.attrelid = to_regclass('public.' || x.tbl) AND a.attname = x.col AND NOT a.attisdropped LEFT JOIN pg_type ty ON ty.oid = a.atttypid WHERE ty.typname IS DISTINCT FROM 'vector'; IF bad IS NOT NULL THEN RAISE EXCEPTION 'staging restore: run the vector post-load first, these are not vector (%); nothing changed', bad; END IF; END $guard$;

-- 2. R2: public -> auth foreign keys are recorded and dropped, never kept.
DO $r2$ DECLARE r record; BEGIN FOR r IN SELECT quote_ident(tn.nspname) || '.' || quote_ident(t.relname) AS tbl, c.conname, pg_get_constraintdef(c.oid) AS def FROM pg_constraint c JOIN pg_class t ON t.oid = c.conrelid JOIN pg_namespace tn ON tn.oid = t.relnamespace JOIN pg_class rt ON rt.oid = c.confrelid JOIN pg_namespace rn ON rn.oid = rt.relnamespace WHERE c.contype = 'f' AND tn.nspname = 'public' AND rn.nspname = 'auth' LOOP INSERT INTO migration_audit.saved_foreign_keys (table_name, constraint_name, definition, references_auth) VALUES (r.tbl, r.conname, r.def, true) ON CONFLICT (table_name, constraint_name) DO UPDATE SET definition = EXCLUDED.definition, references_auth = true; EXECUTE format('ALTER TABLE %s DROP CONSTRAINT %I', r.tbl, r.conname); END LOOP; END $r2$;

-- 3. Indexes.
DO $idx$ DECLARE r record; BEGIN FOR r IN SELECT index_name, definition FROM migration_audit.saved_indexes ORDER BY 1 LOOP IF to_regclass(r.index_name) IS NULL THEN EXECUTE regexp_replace(r.definition, '^CREATE (UNIQUE )?INDEX ', 'CREATE \1INDEX IF NOT EXISTS '); END IF; UPDATE migration_audit.saved_indexes SET restored_at = coalesce(restored_at, now()) WHERE index_name = r.index_name; END LOOP; END $idx$;

-- 4. Foreign keys, except public -> auth.
DO $fk$ DECLARE r record; BEGIN FOR r IN SELECT table_name, constraint_name, definition FROM migration_audit.saved_foreign_keys WHERE NOT references_auth ORDER BY 1, 2 LOOP IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = to_regclass(r.table_name) AND conname = r.constraint_name) THEN EXECUTE format('ALTER TABLE %s ADD CONSTRAINT %I %s', r.table_name, r.constraint_name, CASE WHEN r.definition ~ 'NOT VALID$' THEN r.definition ELSE r.definition || ' NOT VALID' END); END IF; UPDATE migration_audit.saved_foreign_keys SET restored_at = coalesce(restored_at, now()) WHERE table_name = r.table_name AND constraint_name = r.constraint_name; END LOOP; END $fk$;

-- 5. Views, shallowest first, with options, grants and comment.
DO $views$ DECLARE r record; g text; BEGIN FOR r IN SELECT * FROM migration_audit.saved_views ORDER BY depth, view_name LOOP IF to_regclass(r.view_name) IS NULL THEN EXECUTE format('CREATE %s %s%s AS %s', CASE r.relkind WHEN 'm' THEN 'MATERIALIZED VIEW' ELSE 'VIEW' END, r.view_name, CASE WHEN r.reloptions IS NULL THEN '' ELSE ' WITH (' || array_to_string(r.reloptions, ', ') || ')' END, r.definition); FOREACH g IN ARRAY r.grants LOOP EXECUTE g; END LOOP; IF r.comment IS NOT NULL THEN EXECUTE format('COMMENT ON %s %s IS %L', CASE r.relkind WHEN 'm' THEN 'MATERIALIZED VIEW' ELSE 'VIEW' END, r.view_name, r.comment); END IF; END IF; UPDATE migration_audit.saved_views SET restored_at = coalesce(restored_at, now()) WHERE view_name = r.view_name; END LOOP; END $views$;

-- 6. End state, or roll everything back.
DO $assert$ DECLARE bad text; BEGIN SELECT string_agg(table_name || '.' || constraint_name, ', ') INTO bad FROM migration_audit.saved_foreign_keys s WHERE NOT references_auth AND NOT EXISTS (SELECT 1 FROM pg_constraint c WHERE c.conrelid = to_regclass(s.table_name) AND c.conname = s.constraint_name); IF bad IS NOT NULL THEN RAISE EXCEPTION 'staging restore: foreign keys not restored (%); rolled back', bad; END IF; SELECT string_agg(view_name, ', ') INTO bad FROM migration_audit.saved_views WHERE to_regclass(view_name) IS NULL; IF bad IS NOT NULL THEN RAISE EXCEPTION 'staging restore: views not restored (%); rolled back', bad; END IF; SELECT string_agg(index_name, ', ') INTO bad FROM migration_audit.saved_indexes WHERE to_regclass(index_name) IS NULL; IF bad IS NOT NULL THEN RAISE EXCEPTION 'staging restore: indexes not restored (%); rolled back', bad; END IF; SELECT string_agg(c.conname, ', ') INTO bad FROM pg_constraint c JOIN pg_class t ON t.oid = c.conrelid JOIN pg_namespace tn ON tn.oid = t.relnamespace JOIN pg_class rt ON rt.oid = c.confrelid JOIN pg_namespace rn ON rn.oid = rt.relnamespace WHERE c.contype = 'f' AND tn.nspname = 'public' AND rn.nspname = 'auth'; IF bad IS NOT NULL THEN RAISE EXCEPTION 'staging restore: public -> auth foreign keys remain (%); rolled back', bad; END IF; END $assert$;
